#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>

/* Return 1 if the string consists only of decimal digits (no sign) */
static int all_digits(const char *s)
{
    if (*s == '\0')
        return 0;               /* empty string is not a number */
    while (*s) {
        if (!isdigit((unsigned char)*s))
            return 0;
        s++;
    }
    return 1;
}

/* Compute the sum of proper divisors of n (excluding n itself) */
static long sum_proper_divisors(long n)
{
    long sum = 0;
    for (long d = 1; d * d <= n; ++d) {
        if (n % d == 0) {
            long other = n / d;
            if (d != n)               /* d is a proper divisor */
                sum += d;
            if (other != d && other != n)   /* paired divisor, also proper */
                sum += other;
        }
    }
    return sum;
}

int main(int argc, char *argv[])
{
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    char *endptr = NULL;
    long n = strtol(argv[1], &endptr, 10);

    /* strtol failed or there were extra characters */
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    /* The original program only accepted positive integers */
    if (n <= 0) {
        puts("BAD_INPUT");
        return 0;
    }

    if (n > 1000000L) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    long sum = sum_proper_divisors(n);

    if (sum == n)
        printf("n=%ld sum=%ld perfect\n", n, sum);
    else if (sum > n)
        printf("n=%ld sum=%ld abundant\n", n, sum);
    else
        printf("n=%ld sum=%ld deficient\n", n, sum);

    return 0;
}
